import hashlib,json,re,sys
from pathlib import Path
policy,extract,call,funding,form,prior,controls,milestone,out=map(Path,sys.argv[1:])
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
data=json.loads(extract.read_text())
assert sha(policy)==data['source_sha256']
lines={x['line']:x['text'] for x in data['passages']}
for n in (48,49,50,52,53):
    assert lines[n].replace('’',"'")[:65] in policy.read_text()
def links(p):
    return [x for x in re.findall(r'href=["\']([^"\']+)["\']',p.read_text()) if 'generativeai' in x.lower()]
doc={'decision':'Do not submit an AI-authored proposal or plan autonomous AI production of funded artifacts under policy 2.0. Preserve the executed CSV milestone for other channels.', 'policy_url':data['source_url'],'source_hashes':{str(p):sha(p) for p in (policy,call,funding,form,prior,controls,milestone)},'call_material_policy_links':{str(p):links(p) for p in (call,funding,form)},'policy_quotes':{n:lines[n] for n in (42,45,48,49,50,52,53,54,55,67)},'scope':'Policy 2.0 describes coverage of applications submitted to NLnet and all work delivered within its grants. The source refers to transitional arrangements for NGI Zero. This decision covers the proposed autonomous workflow.','reopen':'Applicable first-party terms or written confirmation expressly permitting the proposed workflow for this call, or a separately evidenced eligible human-led application and delivery plan complying with the applicable policy, with existing AI-generated code disclosed as required. No exception is assumed.','reusable_milestone':str(milestone),'executed_controls':str(controls),'submission':'none','award':'none verified','settlement':'none verified'}
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(doc,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({k:doc[k] for k in ('decision','call_material_policy_links')}))
